/** @returns {Uint8Array} the mark, decoded for docx's ImageRun. */
function logoBytes() {
  if (typeof atob === 'function') {
    const bin = atob(LOGO_BASE64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }
  return Uint8Array.from(Buffer.from(LOGO_BASE64, 'base64'));
}

/* Native pixel size, so callers can scale without guessing the aspect ratio. */
const LOGO_WIDTH = 520;
const LOGO_HEIGHT = 436;

export { logoBytes, LOGO_WIDTH, LOGO_HEIGHT };
